{{ config(
            materialized='table',
                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.clickstream_metabase as with flat as ( select a.request_date, a.source, f.value::string as shopify_product_id, a.user_type, a.source_widget, a.source_widget_id, a.product_click, a.product_impression, a.add_to_cart, a.initiate_payment, a.purchase from snitch_db.maplemonk.s3_clickstream a, lateral flatten(input => try_parse_json(a._ab_additional_properties::string)) f where f.key = \'shopify_product_id\' ) select a.request_date, dayname(a.request_date::date) as day, a.source, a.shopify_product_id, a.user_type, a.source_widget, a.source_widget_id, a.product_click::int as clicks, a.product_impression::int as impression, a.add_to_cart::int as add_to_cart, a.initiate_payment::int as payment, a.purchase::int as purchase, b.sku_group, b.category from flat a left join snitch_db.maplemonk.base_product b on a.shopify_product_id = b.id::string ; CREATE OR REPLACE TABLE snitch_db.maplemonk.clickstream_pareto_daily_sku AS WITH daily_stats AS ( SELECT REQUEST_DATE::DATE AS request_date, CATEGORY AS category, SKU_GROUP AS sku_group, COALESCE(SUM(IMPRESSION), 0) AS daily_impressions, COALESCE(SUM(CLICKS), 0) AS daily_clicks, COALESCE(SUM(ADD_TO_CART), 0) AS daily_atc, COALESCE(SUM(PURCHASE), 0) AS daily_purchases FROM snitch_db.maplemonk.clickstream_metabase WHERE CATEGORY IS NOT NULL AND LOWER(TRIM(CATEGORY)) NOT IN (\'none\', \'\') AND SKU_GROUP IS NOT NULL AND LOWER(TRIM(SKU_GROUP)) NOT IN (\'none\', \'\') GROUP BY 1, 2, 3 ), daily_ranked AS ( SELECT *, COUNT(*) OVER (PARTITION BY request_date) AS total_skus_that_day, ROW_NUMBER() OVER (PARTITION BY request_date ORDER BY daily_clicks DESC, sku_group) AS daily_rank, COUNT(*) OVER (PARTITION BY request_date, category) AS skus_in_category_that_day, ROW_NUMBER() OVER (PARTITION BY request_date, category ORDER BY daily_clicks DESC, sku_group) AS category_daily_rank FROM daily_stats ) SELECT request_date, category, sku_group, daily_impressions, daily_clicks, daily_atc, daily_purchases, COALESCE(ROUND(daily_purchases * 100.0 / NULLIF(daily_clicks, 0), 2), 0) AS conversion_pct, daily_rank, total_skus_that_day, IFF(daily_rank <= CEIL(total_skus_that_day * 0.20), 1, 0) AS is_top_20, IFF(daily_rank <= CEIL(total_skus_that_day * 0.20), \'Top 20%\', \'Bottom 80%\') AS overall_bucket, category_daily_rank, skus_in_category_that_day, IFF(category_daily_rank <= CEIL(skus_in_category_that_day * 0.20), \'Top 20%\', \'Bottom 80%\') AS category_bucket, CURRENT_TIMESTAMP() AS refreshed_at FROM daily_ranked; CREATE OR REPLACE TABLE snitch_db.maplemonk.clickstream_pareto_summary AS SELECT request_date AS date, COUNT_IF(is_top_20 = 1) AS top_20_sku_count, COUNT_IF(is_top_20 = 0) AS bottom_80_sku_count, MAX(total_skus_that_day) AS total_active_skus, SUM(IFF(is_top_20 = 1, daily_clicks, 0)) AS top_20_clicks, SUM(IFF(is_top_20 = 0, daily_clicks, 0)) AS bottom_80_clicks, SUM(daily_clicks) AS total_clicks, SUM(IFF(is_top_20 = 1, daily_purchases, 0)) AS top_20_purchases, SUM(IFF(is_top_20 = 0, daily_purchases, 0)) AS bottom_80_purchases, SUM(daily_purchases) AS total_purchases, COALESCE(ROUND(SUM(IFF(is_top_20 = 1, daily_purchases, 0)) * 100.0 / NULLIF(SUM(IFF(is_top_20 = 1, daily_clicks, 0)), 0), 2), 0) AS top_20_conversion_rate, COALESCE(ROUND(SUM(IFF(is_top_20 = 0, daily_purchases, 0)) * 100.0 / NULLIF(SUM(IFF(is_top_20 = 0, daily_clicks, 0)), 0), 2), 0) AS bottom_80_conversion_rate, COALESCE(ROUND(SUM(daily_purchases) * 100.0 / NULLIF(SUM(daily_clicks), 0), 2), 0) AS overall_conversion_rate, COALESCE(ROUND(SUM(IFF(is_top_20 = 1, daily_clicks, 0)) * 100.0 / NULLIF(SUM(daily_clicks), 0), 2), 0) AS top_20_click_share_pct, COALESCE(ROUND(SUM(IFF(is_top_20 = 1, daily_purchases, 0)) * 100.0 / NULLIF(SUM(daily_purchases), 0), 2), 0) AS top_20_purchase_share_pct, MAX(refreshed_at) AS refreshed_at FROM snitch_db.maplemonk.clickstream_pareto_daily_sku GROUP BY 1; CREATE OR REPLACE TABLE snitch_db.maplemonk.clickstream_pareto_category_daily AS SELECT request_date AS date, category, COUNT_IF(is_top_20 = 1) AS skus_in_overall_top_20, COUNT_IF(is_top_20 = 0) AS skus_in_overall_bottom_80, COUNT(*) AS total_skus_in_category, COALESCE(ROUND(COUNT_IF(is_top_20 = 1) * 100.0 / NULLIF(SUM(COUNT_IF(is_top_20 = 1)) OVER (PARTITION BY request_date), 0), 2), 0) AS share_of_top_20_skus_pct, SUM(IFF(is_top_20 = 1, daily_clicks, 0)) AS top_20_clicks, COALESCE(ROUND(SUM(IFF(is_top_20 = 1, daily_clicks, 0)) * 100.0 / NULLIF(SUM(SUM(IFF(is_top_20 = 1, daily_clicks, 0))) OVER (PARTITION BY request_date), 0), 2), 0) AS share_of_top_20_clicks_pct, SUM(IFF(is_top_20 = 1, daily_purchases, 0)) AS top_20_purchases, COALESCE(ROUND(SUM(IFF(is_top_20 = 1, daily_purchases, 0)) * 100.0 / NULLIF(SUM(SUM(IFF(is_top_20 = 1, daily_purchases, 0))) OVER (PARTITION BY request_date), 0), 2), 0) AS share_of_top_20_purchases_pct, COUNT_IF(category_bucket = \'Top 20%\') AS category_top_20_sku_count, COALESCE(ROUND(SUM(IFF(category_bucket = \'Top 20%\', daily_clicks, 0)) * 100.0 / NULLIF(SUM(daily_clicks), 0), 2), 0) AS category_top_20_click_share_pct, MAX(refreshed_at) AS refreshed_at FROM snitch_db.maplemonk.clickstream_pareto_daily_sku GROUP BY 1, 2;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SNITCH_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            